// Tiny WebAudio synth: GB-style square wave SFX + simple looping melodies.
window.Audio2 = (() => {
  let ctx = null, musicTimer = null, musicGain = null, current = null;

  function unlock() {
    if (!ctx) {
      ctx = new (window.AudioContext || window.webkitAudioContext)();
      musicGain = ctx.createGain();
      musicGain.gain.value = 0.06;
      musicGain.connect(ctx.destination);
      if (current) playMusic(current);
    }
    if (ctx.state === 'suspended') ctx.resume();
  }

  function tone(freq, dur, vol = 0.08, type = 'square', when = 0, slide = 0) {
    if (!ctx) return;
    const o = ctx.createOscillator(), g = ctx.createGain();
    o.type = type; o.frequency.value = freq;
    if (slide) o.frequency.linearRampToValueAtTime(freq + slide, ctx.currentTime + when + dur);
    g.gain.setValueAtTime(vol, ctx.currentTime + when);
    g.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + when + dur);
    o.connect(g); g.connect(ctx.destination);
    o.start(ctx.currentTime + when); o.stop(ctx.currentTime + when + dur + 0.02);
  }

  const N = (s) => 440 * Math.pow(2, (s - 9) / 12); // semitones from C4
  // Songs: arrays of [semitone-from-C4 (null=rest), beats]
  const SONGS = {
    overworld: { bpm: 160, notes: [[7,1],[7,1],[9,1],[12,1],[9,1],[7,1],[4,2],[5,1],[7,1],[9,2],[7,2],[4,1],[2,1],[0,2],[null,2],[0,1],[2,1],[4,2],[7,1],[9,1],[7,2],[5,2],[4,2],[2,4]] },
    battle: { bpm: 200, notes: [[0,.5],[0,.5],[0,.5],[0,.5],[-1,.5],[-1,.5],[-1,.5],[-1,.5],[-2,.5],[-2,.5],[-2,.5],[-2,.5],[-3,.5],[-3,.5],[-3,.5],[-3,.5],[0,1],[3,1],[7,2],[5,1],[3,1],[0,2],[3,1],[7,1],[12,2],[10,1],[7,1],[3,2],[0,2]] },
    center: { bpm: 140, notes: [[4,1],[2,1],[0,1],[2,1],[4,1],[4,1],[4,2],[2,1],[2,1],[2,2],[4,1],[7,1],[7,2]] },
  };

  function playMusic(name) {
    current = name;
    if (musicTimer) { clearTimeout(musicTimer); musicTimer = null; }
    if (!ctx || !name) return;
    const song = SONGS[name];
    if (!song) return;
    const beat = 60 / song.bpm;
    let i = 0;
    const step = () => {
      if (current !== name) return;
      const [note, beats] = song.notes[i];
      if (note !== null) {
        const o = ctx.createOscillator(), g = ctx.createGain();
        o.type = 'square'; o.frequency.value = N(note);
        g.gain.setValueAtTime(1, ctx.currentTime);
        g.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + beats * beat * 0.9);
        o.connect(g); g.connect(musicGain);
        o.start(); o.stop(ctx.currentTime + beats * beat);
      }
      i = (i + 1) % song.notes.length;
      musicTimer = setTimeout(step, beats * beat * 1000);
    };
    step();
  }

  return {
    unlock,
    music: playMusic,
    stopMusic: () => playMusic(null),
    beep: () => tone(880, 0.05, 0.04),
    select: () => tone(1200, 0.06, 0.05),
    hit: () => tone(150, 0.12, 0.1, 'sawtooth'),
    superHit: () => { tone(200, 0.08, 0.1, 'sawtooth'); tone(120, 0.15, 0.1, 'sawtooth', 0.07); },
    weakHit: () => tone(300, 0.08, 0.05, 'triangle'),
    faint: () => { tone(400, 0.15, 0.08, 'square', 0, -300); tone(200, 0.3, 0.08, 'square', 0.12, -150); },
    levelUp: () => { [0, 4, 7, 12].forEach((s, i) => tone(N(s + 12), 0.09, 0.06, 'square', i * 0.08)); },
    heal: () => { [4, 9, 14].forEach((s, i) => tone(N(s), 0.12, 0.06, 'square', i * 0.12)); },
    catchClick: () => tone(523, 0.08, 0.07),
    catchSuccess: () => { [7, 7, 5, 9, 7].forEach((s, i) => tone(N(s + 12), 0.1, 0.06, 'square', i * 0.1)); },
    evolve: () => { [0, 2, 4, 5, 7, 9, 11, 12].forEach((s, i) => tone(N(s + 12), 0.07, 0.05, 'square', i * 0.06)); },
    run: () => tone(800, 0.2, 0.06, 'square', 0, -500),
    thrown: () => tone(300, 0.15, 0.06, 'square', 0, 400),
  };
})();
